<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
import {penaltyFrame,resolvePenalty,targetZones,type PenaltyShot} from './penalty'
const emit=defineEmits<{exit:[]}>()
const target=ref(2),phase=ref<'aim'|'shooting'|'result'>('aim'),shot=ref<PenaltyShot>(),progress=ref(0),paused=ref(false),reduced=ref(true),first=ref<HTMLButtonElement>(),shootButton=ref<HTMLButtonElement>(),retryButton=ref<HTMLButtonElement>()
let frame=0,last=0,media:MediaQueryList|undefined
const pose=computed(()=>shot.value?penaltyFrame(shot.value,progress.value):{ballX:350,ballY:355,ballRadius:12,keeperX:350,keeperY:205,keeperAngle:0})
const result=computed(()=>phase.value==='result'?(shot.value?.saved?'Saved! The keeper read your shot.':'Goal! You beat the keeper.'):'')
function finish(){cancelAnimationFrame(frame);progress.value=1;phase.value='result';paused.value=false;void nextTick(()=>retryButton.value?.focus())}
function tick(now:number){if(phase.value!=='shooting'||paused.value)return;progress.value=Math.min(1,progress.value+Math.min(.08,(now-last)/1000)/1.15);last=now;if(progress.value>=1)finish();else frame=requestAnimationFrame(tick)}
function fire(){if(phase.value!=='aim')return;shot.value=resolvePenalty(target.value,Math.random());progress.value=0;phase.value='shooting';if(reduced.value||document.hidden)finish();else{last=performance.now();frame=requestAnimationFrame(tick)}}
function pause(){paused.value=!paused.value;cancelAnimationFrame(frame);if(!paused.value){last=performance.now();frame=requestAnimationFrame(tick)}}
async function retry(){cancelAnimationFrame(frame);phase.value='aim';shot.value=undefined;progress.value=0;paused.value=false;await nextTick();shootButton.value?.focus()}
function preference(){reduced.value=media?.matches??true;if(reduced.value&&phase.value==='shooting')finish()}
function hidden(){if(document.hidden&&phase.value==='shooting')finish()}
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');preference();media.addEventListener('change',preference);document.addEventListener('visibilitychange',hidden);first.value?.focus()})
onBeforeUnmount(()=>{cancelAnimationFrame(frame);media?.removeEventListener('change',preference);document.removeEventListener('visibilitychange',hidden)})
</script>
<template><section class="penalty-game" aria-label="Local penalty shootout"><header class="penalty-heading"><div><p class="eyebrow">PITCHSIDE / LOCAL MINI-GAME</p><h2>One ball. Beat the keeper.</h2></div><button class="penalty-exit" @click="emit('exit')">Exit penalty ↗</button></header><p class="penalty-instruction">Choose a target inside the goal, then shoot. The keeper chooses an independent dive.</p><div class="penalty-stage" :data-phase="phase" :data-outcome="phase==='result'?(shot?.saved?'saved':'goal'):undefined"><svg viewBox="0 0 700 400" role="img" aria-label="Penalty area, goal net and goalkeeper"><defs><linearGradient id="penalty-turf" x2="0" y2="1"><stop stop-color="#153f34" /><stop offset="1" stop-color="#0e2427" /></linearGradient><pattern id="penalty-net" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" stroke="#86b4aa" stroke-width=".7" fill="none" /></pattern></defs><rect width="700" height="400" fill="#102429" /><path d="M70 70L630 70L700 400H0Z" fill="url(#penalty-turf)" /><g stroke="#436c65" fill="none"><path d="M0 345H700M65 70L0 400M635 70L700 400M85 300H615L580 85H120Z" /><path d="M215 300Q350 235 485 300" /></g><path d="M120 70L145 40H555L580 70V260H120Z" fill="#0b1a1d" stroke="#5d8d83" /><path d="M120 70H580V260H120Z" fill="url(#penalty-net)" /><path d="M120 70L145 40H555L580 70M145 40V235L120 260M555 40V235L580 260M145 235H555" stroke="#71978f" stroke-width="2" fill="none" /><path d="M120 260V70H580V260" stroke="#e5ffef" stroke-width="7" fill="none" /><ellipse cx="350" cy="358" rx="21" ry="5" fill="#06141499" /><circle cx="350" cy="356" r="3" fill="#c3d6bb" /><g class="penalty-keeper" :transform="`translate(${pose.keeperX} ${pose.keeperY}) rotate(${pose.keeperAngle})`"><ellipse cy="37" rx="30" ry="5" fill="#06141488" /><path d="M-10 5L-18 35M10 5L18 35" stroke="#a6c2be" stroke-width="10" stroke-linecap="round" /><path d="M-12-24L-35-9M12-24L35-9" stroke="#62e0f0" stroke-width="10" stroke-linecap="round" /><path d="M-15-27H15L12 9H-12Z" fill="#62e0f0" /><circle cy="-40" r="11" fill="#e0bba2" /><path d="M-10-44Q0-57 10-44" fill="#19343a" /><rect x="-42" y="-18" width="13" height="17" rx="4" fill="#bcff63" /><rect x="29" y="-18" width="13" height="17" rx="4" fill="#bcff63" /><text y="-7" text-anchor="middle" font-size="12" fill="#102126" font-weight="700">1</text></g><g :transform="`translate(${pose.ballX} ${pose.ballY})`"><circle :r="pose.ballRadius" fill="#f5fff5" stroke="#173838" stroke-width="1.5" /><path :d="`M0 ${-pose.ballRadius*.6}L${pose.ballRadius*.57} ${-pose.ballRadius*.18}L${pose.ballRadius*.35} ${pose.ballRadius*.5}H${-pose.ballRadius*.35}L${-pose.ballRadius*.57} ${-pose.ballRadius*.18}Z`" fill="#132b2d" /></g></svg><div class="goal-targets" role="group" aria-label="Choose shot target"><button v-for="zone in targetZones" :key="zone.id" :ref="zone.id===0?(el)=>{first=el as HTMLButtonElement}:undefined" :aria-label="zone.label" :aria-pressed="target===zone.id" :disabled="phase!=='aim'" @click="target=zone.id"><span>{{ zone.label }}</span><i v-if="target===zone.id" aria-hidden="true">+</i></button></div><span v-if="phase==='shooting'" class="penalty-flight" aria-hidden="true">{{ paused?'SHOT PAUSED':'BALL IN FLIGHT' }}</span></div><div class="penalty-controls"><p role="status" aria-live="polite">{{ result || (phase==='shooting'?(paused?'Shot paused. Resume or exit.':'Shot in flight…'):`Aim: ${targetZones[target]?.label}. Ready when you are.`) }}</p><button v-if="phase==='aim'" ref="shootButton" class="ui-button ui-button--primary" @click="fire">Shoot ↗</button><button v-else-if="phase==='shooting'" class="ui-button ui-button--secondary" @click="pause">{{ paused?'Resume shot':'Pause shot' }}</button><button v-else ref="retryButton" class="ui-button ui-button--primary" @click="retry">Try again ↻</button></div><small class="penalty-disclaimer">Local illustrative game · no match scores or account points are changed. Match data is separate.</small></section></template>
